QUESTIONS.push(
{"id": "DL2-001", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-acetylcholine-nic", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Acetylcholine acts at the neuromuscular junction as which of the following?", "options": [{"t": "A depolarizing direct agonist", "correct": true, "why": "Acetylcholine opens the muscle nicotinic (Nm) channel and depolarizes the end plate; it is listed with succinylcholine as a depolarizing agent."}, {"t": "A non-depolarizing competitive antagonist", "correct": false, "why": "That is the curare-like drugs (rocuronium, vecuronium, pancuronium), which stop the channel from opening."}, {"t": "An indirect antagonist of acetylcholinesterase", "correct": false, "why": "That is neostigmine, pyridostigmine and the other cholinesterase inhibitors; they raise acetylcholine rather than being it."}, {"t": "An inhibitor of acetylcholine release", "correct": false, "why": "That is botulinum toxin, which acts on the presynaptic terminal."}, {"t": "A partial agonist at α4β2 receptors", "correct": false, "why": "That is varenicline, at the neuronal nicotinic (Nn) receptor in the brain."}], "teach": "The neuromuscular junction drugs split into direct and indirect. Direct drugs bind the muscle nicotinic (Nm) receptor: depolarizing agents are agonists (acetylcholine and succinylcholine); non-depolarizing agents are competitive antagonists (curare-like drugs). Indirect drugs block acetylcholinesterase and raise synaptic acetylcholine.", "quote": "Now, this group is gonna be divided in two different categories, depolarizing, which is the same thing as an agonist, it is activating the receptors, and non-depolarizing, which is gonna be the antagonist. … Acetylcholine is an agonist, but it's broken down very quickly.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 12; transcript 10/5"},
{"id": "DL2-002", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-varenicline", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which of the following describes the mechanism of action of varenicline?", "options": [{"t": "Partial agonist at α4β2 neuronal nicotinic (Nn) receptors", "correct": true, "why": "Varenicline is a selective partial agonist at the central α4β2 Nn receptor, with high affinity."}, {"t": "Full agonist at muscle nicotinic (Nm) receptors", "correct": false, "why": "A full agonist at Nm that depolarizes the end plate is succinylcholine (and acetylcholine)."}, {"t": "Competitive antagonist at muscle nicotinic (Nm) receptors", "correct": false, "why": "That is the curare-like (non-depolarizing) drugs."}, {"t": "Reversible inhibitor of acetylcholinesterase", "correct": false, "why": "That is physostigmine, neostigmine and the other cholinesterase inhibitors (indirect antagonists)."}], "teach": "Varenicline binds the α4β2 neuronal nicotinic (Nn) receptor in the central nervous system with high affinity and activates it only partially. That decreases craving and withdrawal and blunts the effect of nicotine, so it is used for smoking cessation.", "quote": "So what is the mechanism of action for Chantix? So it's a partial agonist to what? The alpha 4, beta 2, nicotinic, what type of nicotinic receptor? And for what neuronal.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 7–8; transcript 10/5"},
{"id": "DL2-003", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "soa-varenicline", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Where is the site of action of varenicline?", "options": [{"t": "Neuronal nicotinic (Nn) receptors in the brain", "correct": true, "why": "The site of action is the central nervous system, at α4β2 Nn receptors."}, {"t": "Muscle nicotinic (Nm) receptors at the neuromuscular junction", "correct": false, "why": "That is the site of succinylcholine and the curare-like drugs."}, {"t": "M3 receptors in the ciliary muscle of the eye", "correct": false, "why": "That is where echothiophate’s effect is produced."}, {"t": "The presynaptic terminal of motor neurons", "correct": false, "why": "That is the site of botulinum toxin, which prevents acetylcholine release."}], "teach": "Varenicline’s site of action is the central nervous system. Its receptor there is the α4β2 neuronal nicotinic (Nn) receptor; the muscle nicotinic (Nm) receptor at the neuromuscular junction is a different receptor.", "quote": "If it's neuronal, that should be a key that the site of action that drugs where in the brain.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 8; transcript 10/5"},
{"id": "DL2-004", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "adr-varenicline", "tags": ["drug-list", "list"], "source": "both", "fg": "classes", "multi": true, "stem": "Which adverse effects are reported for varenicline? Select all that apply.", "options": [{"t": "Nausea and vomiting", "correct": true, "why": "Listed as the most common GI side effect (nausea 16–40%)."}, {"t": "Headache", "correct": true, "why": "Listed under central nervous system side effects."}, {"t": "Insomnia", "correct": true, "why": "Listed under central nervous system side effects."}, {"t": "Depression", "correct": true, "why": "Listed under central nervous system side effects; the site of action is the brain."}, {"t": "Flatulence", "correct": true, "why": "A gastrointestinal complaint: patients “get a lot of gas”."}, {"t": "Hyperkalemia", "correct": false, "why": "Hyperkalemia is a succinylcholine adverse reaction (muscle cells lose K+)."}, {"t": "Histamine release with hypotension", "correct": false, "why": "That is a curare-like drug adverse reaction (most with atracurium)."}], "teach": "Varenicline acts in the brain, so its side effects include central nervous system effects (headache, insomnia, depression); it is a partial agonist, so it still activates the receptor somewhat. Its gastrointestinal side effects are nausea and vomiting (most common) and flatulence. The drug list also warns of mood and behavioral changes.", "quote": "As such, some of the side effects are gonna be where in the brain, depression, lack of being able to sleep because you are activating the receptors … Uh, there's also some GI side effects. Uh, I don't think if I listed for you guys, but flatulence is a complaint for the patients. They get a lot of gas.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 9; transcript 10/5", "note": "The drug list gives headache, insomnia, suicidal thoughts, depression and flatulence and does not list nausea; the slide lists nausea and vomiting as the most common and does not list suicidal thoughts or flatulence. On 10/5 he added flatulence (“I don’t think if I listed for you guys, but flatulence is a complaint”), so flatulence is keyed with the slide’s effects; suicidal thoughts are not asked."},
{"id": "DL2-005", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-succinylcholine", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which of the following describes the mechanism of action of succinylcholine?", "options": [{"t": "Depolarizing agonist at muscle nicotinic (Nm) receptors", "correct": true, "why": "Succinylcholine opens the nicotinic channel and depolarizes the motor end plate: a depolarizing agent."}, {"t": "Competitive antagonist at muscle nicotinic (Nm) receptors", "correct": false, "why": "That is the non-depolarizing (curare-like) drugs."}, {"t": "Partial agonist at neuronal nicotinic (Nn) receptors", "correct": false, "why": "That is varenicline."}, {"t": "Organophosphate inhibitor of acetylcholinesterase", "correct": false, "why": "That is echothiophate."}], "teach": "Succinylcholine resembles two acetylcholine molecules joined at the alkyl ends. It is an agonist: it opens the nicotinic channel at the neuromuscular junction, but it is not metabolized effectively at the synapse, so the end plate stays depolarized and the muscle is paralyzed.", "quote": "You must know that a sucycholine is an agonist that depolarize or open those ion channels. That's the mechanism of action.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 19–20; transcript 10/5"},
{"id": "DL2-006", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "phase-succinylcholine", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which statement about succinylcholine’s Phase I and Phase II block is CORRECT?", "options": [{"t": "Phase I keeps the end plate depolarized; Phase II blocks the channel", "correct": true, "why": "Phase I: prolonged depolarization (no repolarization). Phase II: channel blockade prevents movement of Na+/K+ and prolongs the paralysis."}, {"t": "Phase I blocks the channel; Phase II keeps the end plate depolarized", "correct": false, "why": "Reverses the two phases."}, {"t": "Both phases are competitive block at the acetylcholine binding site", "correct": false, "why": "Competitive block at the binding site is how curare-like drugs act; succinylcholine is an agonist."}, {"t": "Phase II is produced by inhibition of acetylcholinesterase", "correct": false, "why": "Cholinesterase inhibition is the indirect mechanism of drugs such as neostigmine."}], "teach": "In Phase I succinylcholine opens the channel and, because it is not metabolized effectively at the synapse, keeps the motor end plate depolarized; contraction needs end-plate repolarization (“repriming”), so the muscle is paralyzed. In Phase II the channel is blocked, which prevents movement of Na+ and K+ and prolongs the paralysis.", "quote": "And the first one is that opening of all the receptors. That's called phase one. And then if it stays around longer, now it actually can get lodged inside of that channel. And that will be a phase 2. Now it's blocking anything from going through.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 24; transcript 10/5"},
{"id": "DL2-007", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "adr-succinylcholine", "tags": ["drug-list", "list"], "source": "both", "fg": "classes", "multi": true, "stem": "Which adverse drug reactions are listed for succinylcholine? Select all that apply.", "options": [{"t": "Hyperkalemia", "correct": true, "why": "The muscle cell loses K+ (and gains Ca++ and Na+)."}, {"t": "Hypertension and arrhythmias", "correct": true, "why": "Listed as the cardiovascular adverse reactions."}, {"t": "Post-operative muscle pain (myalgia)", "correct": true, "why": "Caused by unsynchronized contractions."}, {"t": "Hyperthermia", "correct": true, "why": "The muscle fibers keep contracting out of sync, and the patient gets too hot."}, {"t": "Histamine release with marked hypotension", "correct": false, "why": "That is a curare-like drug reaction (atracurium most)."}, {"t": "Miosis and lacrimation", "correct": false, "why": "Those are echothiophate (eye) reactions."}, {"t": "Insomnia and depression", "correct": false, "why": "Those are varenicline reactions."}], "teach": "Succinylcholine’s adverse reactions are hyperkalemia (muscle cells lose K+), hypertension and arrhythmias, post-operative muscle pain and hyperthermia from unsynchronized contractions. It is avoided in renal-deficient and dehydrated patients.", "quote": "so they may get hyperkalemia … So patients can get actually hyperthermia. They get too hot, right, because they can't, their muscles. … so your blood pressure is gonna go up, hypertension, and your heart is gonna be fighting between the parasympathetic and the sympathetic … And patients actually complain of uh muscle pain, myalgia", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 25; transcript 10/5"},
{"id": "DL2-008", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "soa-succinylcholine", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Besides the muscle nicotinic (Nm) receptor at the neuromuscular junction, at increased doses succinylcholine can also stimulate which site?", "options": [{"t": "Autonomic ganglia, and thus the PNS and SNS", "correct": true, "why": "At increased doses succinylcholine stimulates ganglia, and thus the parasympathetic (PNS) and sympathetic (SNS) nervous systems."}, {"t": "Muscarinic M3 receptors in the bladder", "correct": false, "why": "M3 in the bladder is the site of the overactive-bladder antagonists (oxybutynin and others)."}, {"t": "The presynaptic terminal, blocking acetylcholine release", "correct": false, "why": "Blocking release at the presynaptic terminal is botulinum toxin."}, {"t": "α4β2 receptors in the brain", "correct": false, "why": "That is varenicline’s site."}], "teach": "Succinylcholine’s main site is the muscle nicotinic (Nm) receptor at the neuromuscular junction. At increased doses it also stimulates the autonomic ganglia, where neuronal nicotinic (Nn) receptors activate the postganglionic neurons of the parasympathetic nervous system (PNS) and sympathetic nervous system (SNS).", "quote": "So if you infuse for a longer period of time, you're gonna start to open those nicotinic receptors in the ganglia, which is gonna increase your parasympathetic and sympathetic at the same time.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 20; transcript 10/5"},
{"id": "DL2-009", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "ddi-succinylcholine", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "A patient receives succinylcholine together with an inhaled anesthetic such as halothane. Which reaction is this combination associated with?", "options": [{"t": "Malignant hyperthermia", "correct": true, "why": "Listed as the succinylcholine drug–drug interaction with inhaled anesthetics: abnormal Ca++ release from skeletal-muscle stores and muscle heat production."}, {"t": "Histamine release and bronchial spasm", "correct": false, "why": "Histamine release is a curare-like drug reaction (atracurium)."}, {"t": "Hypertensive crisis from dietary tyramine", "correct": false, "why": "That is the phenelzine reaction."}, {"t": "Rebound nasal congestion", "correct": false, "why": "That is the phenylephrine reaction."}], "teach": "With inhaled anesthetics, succinylcholine is associated with malignant hyperthermia: abnormal release of Ca++ from stores in skeletal muscle and heat production by skeletal muscle. Dantrolene is an antagonist at the ryanodine receptor and lowers intracellular Ca++.", "quote": "Uh, this is what I was telling you about that malignant hyperthermia. Their, their body pressure gets really, really high, uh, especially if you combine with an anesthetic that put them to sleep, such as halotane.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 26; transcript 10/5", "note": "The drug list places hyperthermia among succinylcholine’s adverse reactions; the slide places malignant hyperthermia under drug–drug interactions with inhaled anesthetics. On 10/5 he gave both: hyperthermia as an adverse reaction (unsynchronized contraction) and malignant hyperthermia when it is combined with an anesthetic such as halothane. This item keys the interaction."},
{"id": "DL2-010", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-curare", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which of the following describes the mechanism of action of rocuronium?", "options": [{"t": "Competitive antagonist at muscle nicotinic (Nm) receptors", "correct": true, "why": "Rocuronium is a curare-like, non-depolarizing agent: it binds the acetylcholine site and stops the channel from opening."}, {"t": "Depolarizing agonist at muscle nicotinic (Nm) receptors", "correct": false, "why": "That is succinylcholine."}, {"t": "Inhibitor of acetylcholinesterase at the neuromuscular junction", "correct": false, "why": "That is neostigmine and pyridostigmine, which reverse curare-like drugs."}, {"t": "Cleavage of SNARE proteins in the presynaptic terminal", "correct": false, "why": "That is botulinum toxin."}], "teach": "The curare-like (non-depolarizing) drugs — tubocurarine (prototype), mivacurium, vecuronium, rocuronium, pancuronium — are direct competitive antagonists. They bind the acetylcholine binding site on the muscle nicotinic (Nm) receptor without opening it; acetylcholine is needed for muscle contraction, so the muscle is paralyzed.", "quote": "But for our purpose on exam two, all I need you to know is that any karate-like drug is what? A competitive, reversible NM antagonist, and by blocking the NM, what are you gonna get? Paralysis, right?", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 19, 27; transcript 10/5"},
{"id": "DL2-011", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "group-nondepolarizing", "tags": ["drug-list", "list"], "source": "both", "fg": "classes", "multi": true, "stem": "Which drugs are non-depolarizing neuromuscular blocking agents? Select all that apply.", "options": [{"t": "Vecuronium", "correct": true, "why": "A curare-like competitive antagonist at Nm."}, {"t": "Rocuronium", "correct": true, "why": "A curare-like competitive antagonist at Nm."}, {"t": "Pancuronium", "correct": true, "why": "A curare-like competitive antagonist at Nm."}, {"t": "Mivacurium", "correct": true, "why": "A curare-like competitive antagonist at Nm."}, {"t": "Succinylcholine", "correct": false, "why": "Succinylcholine is the depolarizing agent (an agonist)."}, {"t": "Neostigmine", "correct": false, "why": "Neostigmine is a cholinesterase inhibitor; it reverses curare-like drugs."}, {"t": "Varenicline", "correct": false, "why": "Varenicline is a partial agonist at α4β2 neuronal nicotinic (Nn) receptors in the brain; it does not paralyze."}], "teach": "Both drug types cause paralysis. Depolarizing: succinylcholine (agonist, opens nicotinic channels). Non-depolarizing: curare (prototype), mivacurium, vecuronium, rocuronium and pancuronium (competitive antagonists, stop the nicotinic channels from opening). A drug with “cur” in the middle of its name is curare-like: a competitive, reversible muscle nicotinic (Nm) antagonist.", "quote": "However, if you know that it is a C U R in the middle, it doesn't matter if it's vecuronio, Rocuronio, Pencuronio. They're all the same.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 19; transcript 10/5"},
{"id": "DL2-012", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "adr-curare", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "A patient is administered rocuronium. Which of the following is most likely to occur?", "options": [{"t": "Paralysis", "correct": true, "why": "Rocuronium blocks the muscle nicotinic (Nm) receptor, so paralysis occurs every time; it is what the drug is used for."}, {"t": "Diarrhea", "correct": false, "why": "Gut motility is driven through muscarinic receptors; rocuronium blocks only the muscle nicotinic (Nm) receptor."}, {"t": "Vasoconstriction", "correct": false, "why": "Blood vessels respond through adrenergic (sympathetic) receptors; rocuronium blocks the muscle nicotinic (Nm) receptor."}, {"t": "Sedation", "correct": false, "why": "Curare-like drugs do not cross the blood–brain barrier and do not put the patient to sleep."}], "teach": "Rocuronium is a curare-like drug: a competitive, reversible muscle nicotinic (Nm) antagonist, so paralysis always occurs. The other adverse reactions depend on the drug: paralysis of the diaphragm (respiratory paralysis), tachycardia more often with pancuronium, and massive histamine release with atracurium. They have no central nervous system (CNS) effect.", "quote": "If a patient is administered Rocuronium. Which of the following is most likely to occur? … So what we have over here is paralysis. That's always going to happen.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 27, 30, 32; transcript 10/5", "note": "The drug list gives histamine release, hypotension and tachycardia and omits respiratory paralysis; the slide lists respiratory paralysis first, ties tachycardia to pancuronium and histamine release mainly to atracurium (not on the list). On 10/5 he called these drug-dependent and said that for Exam 2 he needs only that any curare-like drug is a competitive, reversible Nm antagonist that causes paralysis, so this item keys paralysis (his in-class question on rocuronium)."},
{"id": "DL2-013", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "cns-curare", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which statement about the curare-like drugs (for example vecuronium) is CORRECT?", "options": [{"t": "They have no central nervous system effect", "correct": true, "why": "The curare-like drugs have no central nervous system effect."}, {"t": "They cross the blood–brain barrier and cause sedation", "correct": false, "why": "They have no central nervous system effect."}, {"t": "They are agonists that keep the end plate depolarized", "correct": false, "why": "That is succinylcholine."}, {"t": "They raise acetylcholine levels at the synapse", "correct": false, "why": "That is the cholinesterase inhibitors."}], "teach": "The curare-like drugs act only at the neuromuscular junction, where they block the muscle nicotinic (Nm) receptor competitively. They have no central nervous system effect, so a paralyzed patient is not sedated by them; they are used as an adjuvant in surgical anesthesia, not as an anesthetic.", "quote": "The key thing for you to remember is these drugs don't cross the blood brain barrier. They have no effect on memory or putting your patient to sleep. They just paralyze your patients.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 27, 32; transcript 10/5"},
{"id": "DL2-014", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "physostigmine", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which statement about physostigmine is CORRECT?", "options": [{"t": "It crosses the blood–brain barrier", "correct": true, "why": "Physostigmine is a tertiary amine and readily penetrates the central nervous system."}, {"t": "It is a quaternary amine that stays out of the brain", "correct": false, "why": "That describes pyridostigmine and neostigmine."}, {"t": "It irreversibly phosphorylates acetylcholinesterase", "correct": false, "why": "That is the organophosphates (echothiophate, parathion, sarin)."}, {"t": "It is a muscarinic receptor antagonist", "correct": false, "why": "Physostigmine inhibits acetylcholinesterase; atropine is the muscarinic antagonist."}], "teach": "Physostigmine is a reversible acetylcholinesterase inhibitor with a longer duration of action. As a tertiary amine it readily penetrates the central nervous system, so it acts in the brain and the periphery, and it is the drug of choice for poisoning by anti-muscarinic agents such as atropine.", "quote": "So one over here, they're both reversible, right, but physostigamine, it crosses the brain, the blood vein barrier, penetrates the blood vein barrier, as neostigimine or pyredos stigmine do not cross the blood vein barrier.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 39; transcript 10/5"},
{"id": "DL2-015", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "physostigmine-use", "tags": ["drug-list", "use"], "source": "both", "fg": "classes", "stem": "A patient is poisoned with atropine. Which cholinesterase inhibitor is the drug of choice?", "options": [{"t": "Physostigmine", "correct": true, "why": "Drug of choice for poisoning by anti-muscarinic agents such as atropine; it reaches the central nervous system."}, {"t": "Neostigmine", "correct": false, "why": "Neostigmine does not cross the blood–brain barrier; its uses are myasthenia gravis and curare reversal."}, {"t": "Pyridostigmine", "correct": false, "why": "Pyridostigmine does not cross the blood–brain barrier; it stays in the periphery."}, {"t": "Echothiophate", "correct": false, "why": "Echothiophate is an organophosphate used in the eye for glaucoma."}], "teach": "Atropine blocks muscarinic receptors in the brain and periphery. Physostigmine raises acetylcholine by inhibiting acetylcholinesterase and, as a tertiary amine, reaches the central nervous system too, so it is the drug of choice for anti-muscarinic poisoning.", "quote": "So, uh, Pfizostigamine typically is gonna be used for as an antidote if somebody has this, uh, you know, overdose on, say, atropine", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 39; transcript 10/5"},
{"id": "DL2-016", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "bbb-ache", "tags": ["drug-list", "list"], "source": "both", "fg": "classes", "multi": true, "stem": "Which acetylcholinesterase inhibitors cross the blood–brain barrier? Select all that apply.", "options": [{"t": "Physostigmine", "correct": true, "why": "Tertiary amine; readily penetrates the central nervous system."}, {"t": "Donepezil", "correct": true, "why": "Lipophilic; crosses the blood–brain barrier (Alzheimer’s disease)."}, {"t": "Rivastigmine", "correct": true, "why": "Lipophilic; crosses the blood–brain barrier (Alzheimer’s disease)."}, {"t": "Neostigmine", "correct": false, "why": "Quaternary amine; does NOT cross the blood–brain barrier."}, {"t": "Pyridostigmine", "correct": false, "why": "Quaternary amine; does NOT cross the blood–brain barrier."}], "teach": "Physostigmine (tertiary amine) and the Alzheimer’s drugs donepezil and rivastigmine (very lipid soluble) cross the blood–brain barrier. Pyridostigmine and neostigmine are quaternary amines and do not, so they act at the neuromuscular junction without central effects.", "quote": "physostigamine, it crosses the brain, the blood vein barrier, penetrates the blood vein barrier, as neostigimine or pyredos stigmine do not cross the blood vein barrier. … For our exam purpose, I only need you to know rivastigamine and donepezil … And those drugs are extremely lipid soluble. They will get to the brain", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1–2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 39–40; transcript 10/5"},
{"id": "DL2-017", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "neostigmine", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which statement about neostigmine and pyridostigmine is CORRECT?", "options": [{"t": "They do not cross the blood–brain barrier", "correct": true, "why": "They are quaternary amines and do NOT cross the blood–brain barrier, so their site of action is the neuromuscular junction."}, {"t": "They are the drugs of choice for atropine poisoning", "correct": false, "why": "That is physostigmine, which reaches the brain."}, {"t": "They are used for early Alzheimer’s disease", "correct": false, "why": "That is donepezil and rivastigmine, which cross the blood–brain barrier."}, {"t": "They block the muscle nicotinic receptor directly", "correct": false, "why": "They inhibit acetylcholinesterase (indirect); direct block of Nm is the curare-like drugs."}], "teach": "Pyridostigmine and neostigmine are reversible acetylcholinesterase inhibitors with a longer duration of action. They are quaternary amines that do not cross the blood–brain barrier, so they act at the neuromuscular junction: they treat myasthenia gravis and reverse curare-like overdose.", "quote": "as neostigimine or pyredos stigmine do not cross the blood vein barrier. … But for myasthenia gravis patients, let's keep the one that stays in the periphery", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 39; transcript 10/5"},
{"id": "DL2-018", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "reverse-curare", "tags": ["drug-list", "use"], "source": "both", "fg": "classes", "stem": "A patient remains paralyzed after a curare-like drug. Which drug reverses the block by raising acetylcholine at the neuromuscular junction?", "options": [{"t": "Neostigmine", "correct": true, "why": "A cholinesterase inhibitor used to reverse curare-like overdose; more acetylcholine competes the curare-like drug off the receptor."}, {"t": "Succinylcholine", "correct": false, "why": "Succinylcholine is itself a paralyzing (depolarizing) drug."}, {"t": "Atropine", "correct": false, "why": "Atropine blocks muscarinic receptors; it does not raise acetylcholine."}, {"t": "Botulinum toxin", "correct": false, "why": "Botulinum toxin lowers acetylcholine release and relaxes muscle."}], "teach": "Curare-like drugs are competitive antagonists, so their block can be overcome by more acetylcholine. Neostigmine and pyridostigmine inhibit acetylcholinesterase, raise synaptic acetylcholine at the neuromuscular junction and reverse the block.", "quote": "So neo stigamine, which does not cross the blood brain barrier but can increase the levels of acetylcholine in the synapse of your skeletal muscle, would give you a better chance of outcompeting karate and regain some movement for your friend. Yes. I have a question similar to this in the exam every year, and about 30% of the class misses it.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 33, 39; transcript 10/5"},
{"id": "DL2-020", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "adr-ache", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which effect is expected from excess acetylcholine after a cholinesterase inhibitor such as donepezil?", "options": [{"t": "Diarrhea and salivation", "correct": true, "why": "Cholinesterase inhibitor adverse reactions are DUMBBELSS (diarrhea, urination, miosis, bradycardia, bronchial constriction, emesis, lacrimation, salivation, stimulation) from excess acetylcholine."}, {"t": "Dry mouth and constipation", "correct": false, "why": "Those are anti-DUMBBELSS effects of muscarinic antagonists."}, {"t": "Mydriasis", "correct": false, "why": "Mydriasis is an anti-DUMBBELSS effect; excess acetylcholine causes miosis."}, {"t": "Tachycardia and bronchial dilation", "correct": false, "why": "Those are atropine effects; excess acetylcholine causes bradycardia and bronchial constriction."}], "teach": "Cholinesterase inhibitors raise synaptic acetylcholine, so their adverse reactions are the symptoms of excess acetylcholine: DUMBBELSS — diarrhea, urination, miosis, bradycardia, bronchial constriction, emesis, lacrimation, salivation, stimulation. Central effects include insomnia, agitation and dizziness.", "quote": "So what kind of side effects do you expect this drug to produce? Dumbbells across the border, right? … So diarrhea, urination, meiosis, bronchial constriction, bradycardia, emesis, which is the same thing as vomiting, lachrymation, salivation, and stimulation of the brain", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 41; transcript 10/5"},
{"id": "DL2-021", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "moa-echothiophate", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which of the following describes the mechanism of action of echothiophate?", "options": [{"t": "Irreversible inhibitor of acetylcholinesterase", "correct": true, "why": "Echothiophate is an organophosphate inhibitor of acetylcholinesterase; organophosphates bind the enzyme covalently (irreversible)."}, {"t": "Reversible inhibitor of acetylcholinesterase in the brain", "correct": false, "why": "That is donepezil and rivastigmine; organophosphates bind the enzyme covalently."}, {"t": "Non-selective muscarinic agonist", "correct": false, "why": "That is pilocarpine and carbachol, which act at the receptor directly."}, {"t": "Muscarinic antagonist in the eye", "correct": false, "why": "That is tropicamide, which dilates the pupil."}], "teach": "Echothiophate is an organophosphate: it inhibits acetylcholinesterase and raises acetylcholine, which increases M3 activation in the ciliary muscle and lowers intraocular pressure by increasing aqueous humor outflow (glaucoma). Organophosphates form a stable covalent bond with the enzyme, so the inhibition is irreversible.", "quote": "So what we can do is we can get echothiofate. … Those are irreversible antagonists to the acetylchonasterase enzyme.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 42, 45; transcript 10/5", "note": "The drug list does not say whether echothiophate is reversible; the slides call organophosphates irreversible, and on 10/5 he called echothiophate an irreversible acetylcholinesterase antagonist. Keyed so."},
{"id": "DL2-022", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "soa-adr-echothiophate", "tags": ["drug-list", "list"], "source": "both", "fg": "classes", "multi": true, "stem": "Echothiophate acts through M3 receptors in the ciliary muscle of the eye. Which adverse reactions does it cause? Select all that apply.", "options": [{"t": "Miosis and blurred vision", "correct": true, "why": "Listed adverse reaction: more M3 activation constricts the pupil."}, {"t": "Lacrimation", "correct": true, "why": "Listed adverse reaction."}, {"t": "Stinging and redness of the eyes", "correct": true, "why": "Listed adverse reaction."}, {"t": "Mydriasis", "correct": false, "why": "Mydriasis is what tropicamide (an M3 antagonist) produces."}, {"t": "Dry eyes", "correct": false, "why": "Raised acetylcholine increases lacrimation, not dryness."}], "teach": "Echothiophate raises acetylcholine and so increases M3 activation in the ciliary muscle (its site of action). Its listed adverse reactions are miosis and blurred vision, lacrimation, and stinging and redness of the eyes.", "quote": "Uh, as a side effect over here, right, it's gonna cause some of meiosis, blurred vision, because your pupils are gonna get smaller. You can't help that. You can get the the lachrymation. Anything that you put in the eye is gonna sting, it's gonna cause a little bit of uh redness to the eye.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 45; transcript 10/5"},
{"id": "DL2-023", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "botox", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which of the following describes the mechanism of action of botulinum toxin?", "options": [{"t": "Blocks acetylcholine release by cleaving SNARE", "correct": true, "why": "Botulinum toxin is an endopeptidase; it cleaves sites on SNARE proteins in the presynaptic terminal, so acetylcholine cannot be released."}, {"t": "Competitively blocks muscle nicotinic (Nm) receptors", "correct": false, "why": "That is the curare-like drugs, which act on the postsynaptic receptor."}, {"t": "Inhibits acetylcholinesterase in the synaptic cleft", "correct": false, "why": "That is the cholinesterase inhibitors, which raise acetylcholine."}, {"t": "Depolarizes the motor end plate", "correct": false, "why": "That is succinylcholine."}], "teach": "Botulinum toxin acts at the presynaptic terminal. Its active fragments are endopeptidases whose substrates are the SNARE proteins needed for vesicle docking and exocytosis; cleaving them blocks acetylcholine release, which relaxes muscle.", "quote": "So Botox is an enzyme that breaks down the snare protein, and if you don't have the snare protein, your vesicles can't bind properly and thus you can't release the cetylcholine.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 46, 50; transcript 10/5", "note": "The drug list colours botulinum toxin red (antagonist); the slides describe it as blocking acetylcholine release, not as a receptor antagonist. Keyed to the slide wording."},
{"id": "DL2-024", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "group-indirect-nmj", "tags": ["drug-list", "list"], "source": "both", "fg": "classes", "multi": true, "stem": "Which drugs act as indirect antagonists by inhibiting acetylcholinesterase? Select all that apply.", "options": [{"t": "Physostigmine", "correct": true, "why": "Cholinesterase inhibitor (acetylcholinesterase antagonist)."}, {"t": "Pyridostigmine", "correct": true, "why": "Cholinesterase inhibitor (acetylcholinesterase antagonist)."}, {"t": "Neostigmine", "correct": true, "why": "Cholinesterase inhibitor (acetylcholinesterase antagonist)."}, {"t": "Rivastigmine", "correct": true, "why": "Cholinesterase inhibitor (acetylcholinesterase antagonist)."}, {"t": "Succinylcholine", "correct": false, "why": "A direct depolarizing agonist at Nm."}, {"t": "Varenicline", "correct": false, "why": "A direct partial agonist at α4β2 Nn."}, {"t": "Botulinum toxin", "correct": false, "why": "Prevents acetylcholine release; it does not inhibit acetylcholinesterase."}], "teach": "Indirect drugs at the neuromuscular junction bind the enzyme that breaks down acetylcholine, not the receptor: acetylcholinesterase antagonists such as physostigmine, pyridostigmine, neostigmine, donepezil, rivastigmine and echothiophate. A drug name ending in “stigmine” marks a cholinesterase inhibitor. Blocking the enzyme raises synaptic acetylcholine.", "quote": "Now, the key for you in the exam is anytime you see a drug that has a stickyine in it, you know it has to do what with the pseudocholinesterase enzyme. … and rivasciamine is an antagonist to the psytocholesterase enzyme.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1–2; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 10, 12; transcript 10/5"},
{"id": "DL2-025", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "nmj", "skill": "drug", "concept": "group-agonist-nmj", "tags": ["drug-list", "list"], "source": "both", "fg": "classes", "multi": true, "stem": "Which drugs in the neuromuscular section of the drug list are direct nicotinic agonists? Select all that apply.", "options": [{"t": "Acetylcholine", "correct": true, "why": "Endogenous agonist; a depolarizing agent at Nm."}, {"t": "Succinylcholine", "correct": true, "why": "Depolarizing agonist at Nm."}, {"t": "Varenicline", "correct": true, "why": "Partial agonist at α4β2 neuronal nicotinic (Nn) receptors."}, {"t": "Rocuronium", "correct": false, "why": "A competitive antagonist (non-depolarizing)."}, {"t": "Neostigmine", "correct": false, "why": "An acetylcholinesterase inhibitor (indirect)."}, {"t": "Botulinum toxin", "correct": false, "why": "Prevents acetylcholine release."}], "teach": "The nicotinic agonists are acetylcholine, nicotine, varenicline (selective partial agonist at α4β2 Nn) and succinylcholine. Curare-like drugs are direct antagonists; cholinesterase inhibitors are indirect.", "quote": "Pennyline is a partial agonist to the NN receptor. Succylcholine is an agonist to the nicotinic receptor. … Acetylcholine is an agonist, but it's broken down very quickly.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 1; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 7; transcript 10/5"},
{"id": "DL2-026", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-bethanechol", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which of the following describes the mechanism of action of bethanechol?", "options": [{"t": "Non-selective, reversible muscarinic (M1–M3) agonist", "correct": true, "why": "Bethanechol is grouped with acetylcholine, methacholine and carbachol as a non-selective muscarinic agonist."}, {"t": "Non-selective, reversible muscarinic (M1–M3) antagonist", "correct": false, "why": "That is atropine."}, {"t": "Reversible inhibitor of acetylcholinesterase", "correct": false, "why": "That is physostigmine and neostigmine (indirect)."}, {"t": "Partial agonist at neuronal nicotinic (Nn) receptors", "correct": false, "why": "That is varenicline."}], "teach": "Acetylcholine, methacholine, carbachol, bethanechol and pilocarpine are non-selective, reversible agonists at the muscarinic receptors (M1, M2, M3); being reversible and competitive, an overdose can be outcompeted by an antagonist. Apart from acetylcholine, they act only at muscarinic receptors, not nicotinic ones.", "quote": "Well, for these drugs, all of them are gonna be non-selective agonists to the M1s, M2s, and M3s. … They're all reversible, so they're all competitive, they're gonna bind, and they're gonna come off.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-Cholinergic-26s.pdf slide 11–12; transcript 10/5"},
{"id": "DL2-027", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "group-musc-agonists", "tags": ["drug-list", "list"], "source": "both", "fg": "classes", "multi": true, "stem": "Which drugs are non-selective muscarinic agonists? Select all that apply.", "options": [{"t": "Methacholine", "correct": true, "why": "Non-selective muscarinic agonist (M1–M3)."}, {"t": "Carbachol", "correct": true, "why": "Non-selective muscarinic agonist (M1–M3)."}, {"t": "Pilocarpine", "correct": true, "why": "Non-selective muscarinic agonist (M1–M3)."}, {"t": "Scopolamine", "correct": false, "why": "A muscarinic antagonist."}, {"t": "Tiotropium", "correct": false, "why": "A muscarinic (M1 and M3) antagonist."}, {"t": "Physostigmine", "correct": false, "why": "An acetylcholinesterase inhibitor; it raises acetylcholine but does not bind the receptor."}], "teach": "The direct muscarinic agonists are acetylcholine, methacholine, carbachol, bethanechol and pilocarpine; all are non-selective (M1, M2, M3) and reversible. The “chol” in methacholine, carbachol and bethanechol marks them as cholinergic; pilocarpine has no “chol” and has to be known by name. Physostigmine reaches the same receptors indirectly by raising acetylcholine.", "quote": "So, I have over here methylcholine, carbacol, Bethenacol, so they all have that call for cholinergic, right? … but for our purpose on the exam, I'm gonna expect you to know pilocarpine as one of the two, OK?", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2–3; PCOL-Cholinergic-26s.pdf slide 11; transcript 10/5"},
{"id": "DL2-029", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "pilocarpine", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which statement about pilocarpine is CORRECT?", "options": [{"t": "It has no effect on nicotinic receptors", "correct": true, "why": "Pilocarpine binds only muscarinic receptors; it does not bind or activate nicotinic receptors."}, {"t": "It binds muscarinic receptors irreversibly", "correct": false, "why": "The muscarinic agonists are all reversible and competitive; they bind and come off."}, {"t": "It is selective for the M2 receptor", "correct": false, "why": "It is a non-selective muscarinic agonist (M1, M2, M3)."}, {"t": "It blocks muscarinic receptors and dries the mouth", "correct": false, "why": "It activates muscarinic receptors; it is used to treat dry mouth."}], "teach": "Pilocarpine is a non-selective, reversible muscarinic agonist (M1, M2, M3). It does not bind or activate nicotinic receptors; among the cholinergic agonists only acetylcholine acts at both nicotinic and muscarinic receptors. At the salivary glands (M3, Gq, ↑Ca++) it causes salivation.", "quote": "What I need you to know is that it does not bind or activate the nicotinic receptors. It only has affinity for the muscarinics.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 14; transcript 10/5"},
{"id": "DL2-030", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "adr-musc-agonist", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "A patient takes bethanechol. Which effect is NOT expected?", "options": [{"t": "Mydriasis", "correct": true, "why": "Muscarinic agonists cause miosis (M3 in the iris); mydriasis is an antagonist effect."}, {"t": "Diarrhea", "correct": false, "why": "Expected: M3 in the gut increases peristalsis and secretion (the D of DUMBBELSS)."}, {"t": "Bradycardia", "correct": false, "why": "Expected: M2 in the heart lowers heart rate."}, {"t": "Bronchial constriction", "correct": false, "why": "Expected: M3 on bronchial smooth muscle."}, {"t": "Salivation", "correct": false, "why": "Expected: M3 on glands."}], "teach": "Muscarinic agonists produce DUMBBELSS: diarrhea, urination, miosis, bradycardia, bronchial constriction, emesis, lacrimation, salivation, stimulation of the central nervous system. Bradycardia comes through M2 in the heart (Gi); the rest of the peripheral effects come through M3 (Gq, ↑Ca++).", "quote": "So when we give an agonist, we're gonna produce what the dumbbells, right? We're gonna increase motilage in tone, so diarrhea, cramping, increased urination, uh, meiosis, which makes your pupil small, bradycardia, bronchial constriction, emesis", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 2; PCOL-Cholinergic-26s.pdf slide 13; transcript 10/5"},
{"id": "DL2-031", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-atropine", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which of the following describes the mechanism of action of atropine?", "options": [{"t": "Non-selective muscarinic (M1–M3) antagonist", "correct": true, "why": "Atropine is a naturally occurring alkaloid that blocks M1, M2 and M3, reversibly."}, {"t": "Non-selective muscarinic (M1–M3) agonist", "correct": false, "why": "That is bethanechol, carbachol and the other muscarinic agonists."}, {"t": "Selective M1 and M3 muscarinic antagonist", "correct": false, "why": "That is tiotropium."}, {"t": "Reversible inhibitor of acetylcholinesterase", "correct": false, "why": "That is physostigmine, which treats atropine poisoning."}], "teach": "Atropine is a non-selective, reversible muscarinic antagonist (M1, M2, M3), acting in the central nervous system and periphery. Blocking the receptors where acetylcholine produces DUMBBELSS gives the anti-DUMBBELSS picture.", "quote": "So when you see drugs like atropine with a trope, what you should be thinking about, those are non-selective muscarinic antagonists that is going to block the M1s, the M2s, and the M3s everywhere else. … This drug is going to be also reversible as well.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 17; transcript 10/5"},
{"id": "DL2-032", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "adr-atropine", "tags": ["drug-list", "list"], "source": "both", "fg": "classes", "multi": true, "stem": "Which effects are expected from an overdose of atropine? Select all that apply.", "options": [{"t": "Tachycardia", "correct": true, "why": "M2 block in the heart → ↑ heart rate."}, {"t": "Mydriasis", "correct": true, "why": "M3 block in the pupil → mydriasis."}, {"t": "Constipation", "correct": true, "why": "M3 block in the gastrointestinal tract → constipation."}, {"t": "Dry mouth", "correct": true, "why": "M3 block on glands → dry mouth."}, {"t": "Sedation", "correct": true, "why": "M1 block in the brain → sedation; at higher doses, hallucinations (“mad as a hatter”)."}, {"t": "Bronchial constriction", "correct": false, "why": "Atropine causes bronchial dilation; constriction is a muscarinic agonist effect."}, {"t": "Miosis", "correct": false, "why": "Miosis is a muscarinic agonist effect; atropine dilates the pupil."}], "teach": "Atropine overdose gives anti-DUMBBELSS: M2 block in the heart raises heart rate; M3 block causes mydriasis, constipation, dry mouth and bronchial dilation; M1 block in the brain causes sedation. Toxicity is summarized as dry as a bone, hot as a pistol, red as a beet, blind as a bat, mad as a hatter.", "quote": "The anti-dumbbells, if it is for diarrhea, you get constipation. … Meiosis, you get the midriasis. Your pupils dilate, instead of getting the bronchial constriction, you get bronchial dilation. You can't cry. You can't sweat, and you're gonna go sedated.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 19, 32; transcript 10/5", "note": "The drug list gives drowsiness for atropine; the slides give its central effects as hallucinations, restlessness and coma (dose-dependent) and give drowsiness for scopolamine. On 10/5 he listed sedation among atropine’s anti-DUMBBELSS effects (“you’re gonna go sedated”), so sedation is keyed."},
{"id": "DL2-033", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "atropine-heart", "tags": ["drug-list", "apply"], "source": "both", "fg": "classes", "stem": "Atropine raises heart rate by blocking which receptor?", "options": [{"t": "M2 in the heart", "correct": true, "why": "M2 (Gi) at the SA and AV node lowers heart rate when acetylcholine binds; blocking it raises heart rate."}, {"t": "M3 in the heart", "correct": false, "why": "M3 mediates smooth muscle, gland, eye and endothelial effects; the cardiac muscarinic receptor is M2."}, {"t": "β1 in the heart", "correct": false, "why": "β1 is the adrenergic receptor that raises heart rate when activated; atropine does not act there."}, {"t": "Neuronal nicotinic (Nn) in ganglia", "correct": false, "why": "Atropine is a muscarinic antagonist, not a nicotinic one."}], "teach": "Acetylcholine slows the heart through M2 (Gi, ↓cAMP) at the SA and AV node. Atropine blocks M2, so the parasympathetic brake is removed and heart rate rises; atropine is used for bradycardia or atrioventricular nodal block.", "quote": "So if I block the M2s, now the sympathetic is unopposed, I'm going to get what? tachycardia.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 10, 19; transcript 10/5"},
{"id": "DL2-034", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "atropine-organophosphate", "tags": ["drug-list", "use"], "source": "both", "fg": "classes", "stem": "In organophosphate poisoning, how does atropine help?", "options": [{"t": "It blocks excess acetylcholine at muscarinic sites", "correct": true, "why": "Atropine (M1, M2, M3 antagonist) reduces the effects of acetylcholine at muscarinic sites: anti-DUMBBELSS."}, {"t": "It regenerates the phosphorylated acetylcholinesterase", "correct": false, "why": "Regenerating the enzyme is pralidoxime (2-PAM), the cholinesterase reactivator."}, {"t": "It lowers acetylcholine release from the nerve terminal", "correct": false, "why": "That is botulinum toxin."}, {"t": "It blocks nicotinic receptors at the neuromuscular junction", "correct": false, "why": "Atropine acts at muscarinic, not nicotinic, receptors."}], "teach": "Organophosphates irreversibly inhibit acetylcholinesterase, so acetylcholine builds up and produces severe DUMBBELSS. Atropine blocks M1, M2 and M3 and reduces the effects of acetylcholine at muscarinic sites; pralidoxime (2-PAM) reactivates the enzyme.", "quote": "You wanna give to pm to break some of those bonds, but it can't stop the dumbbells, right? So how can we manage the dumbbells? By giving atropine.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 44; PCOL-Cholinergic-26s.pdf slide 20; transcript 10/5"},
{"id": "DL2-035", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-scopolamine", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which of the following describes the mechanism of action of scopolamine?", "options": [{"t": "Muscarinic, histamine and serotonin antagonist", "correct": true, "why": "Scopolamine is a non-selective, reversible alkaloid antagonist at muscarinic, histamine and serotonin receptors."}, {"t": "Selective antagonist at M3 receptors in the bladder", "correct": false, "why": "That is solifenacin and trospium."}, {"t": "Non-selective muscarinic (M1–M3) agonist", "correct": false, "why": "That is pilocarpine and the other agonists."}, {"t": "Inhibitor of acetylcholinesterase in the brain", "correct": false, "why": "That is donepezil and the other lipophilic cholinesterase inhibitors."}], "teach": "Scopolamine, like atropine, is a naturally occurring, non-selective and reversible muscarinic antagonist; it also antagonizes histamine and serotonin receptors. It penetrates the central nervous system more rapidly than atropine and is used for motion sickness.", "quote": "We also have the scopolamine, which is a non-selective muscarin. That one is really non-selective. That not only blocks all the muscarinics, but also histamine and serotonin receptors.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 17; transcript 10/5", "note": "The drug list calls scopolamine a non-selective muscarinic antagonist (M1, M2, M3) and does not mention histamine or serotonin receptors; the slide does, and on 10/5 he said the same (“not only blocks all the muscarinics, but also histamine and serotonin receptors”). Keyed to the slide and transcript."},
{"id": "DL2-036", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "scopolamine-cns", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which statement about scopolamine is CORRECT?", "options": [{"t": "It causes drowsiness", "correct": true, "why": "Scopolamine acts in the central nervous system (CNS), which it penetrates more rapidly; drowsiness is among its effects, with euphoria and amnesia."}, {"t": "It does not cross into the CNS", "correct": false, "why": "Not crossing the blood–brain barrier describes neostigmine and pyridostigmine."}, {"t": "It causes salivation and diarrhea", "correct": false, "why": "Those are muscarinic agonist (DUMBBELSS) effects; scopolamine causes dry mouth and constipation."}, {"t": "It blocks only the M2 receptor", "correct": false, "why": "Scopolamine is very non-selective: all muscarinic receptors plus histamine and serotonin receptors."}], "teach": "Scopolamine is a muscarinic antagonist whose site of action is mainly the central nervous system (CNS), which it penetrates more rapidly. It causes drowsiness, euphoria and amnesia; it blocks emesis, but the other anti-DUMBBELSS effects (dry mouth, constipation, urinary retention) come with it.", "quote": "Typical typically people use dromamine or scopolamine for motion sickness. … You're drowsy, but you have to take about 3 hours before you get on the boat", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 24; transcript 10/5"},
{"id": "DL2-037", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "benztropine", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Benztropine is a muscarinic antagonist. Where is its site of action?", "options": [{"t": "The central nervous system", "correct": true, "why": "Benztropine, an atropine analog, blocks M1 in the brain; it is used in Parkinson’s patients for tremor and rigidity."}, {"t": "The lungs, by inhalation", "correct": false, "why": "That is ipratropium, tiotropium, aclidinium and umeclidinium."}, {"t": "M3 receptors in the bladder", "correct": false, "why": "That is the overactive-bladder antagonists."}, {"t": "The eye (pupil)", "correct": false, "why": "That is tropicamide."}], "teach": "In Parkinson’s disease, 70–80% of the dopaminergic neurons from the substantia nigra to the striatum are lost and acetylcholine activity is left unopposed. Benztropine, an analog of atropine, is more selective for M1 receptors in the brain, so it has fewer anti-DUMBBELSS effects elsewhere; it is an add-on to L-dopa for tremor and rigidity.", "quote": "Uh, we can also use an analog of atropine called benztropine. This is a drug used for treatment of Parkinson's disease. … benzotropine is more selective to the beta 1s in the to the M1s in the brain, and it's gonna have less of those anti-dumbbells that you can get, uh, someplace else.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 25; transcript 10/5", "note": "The drug list calls benztropine a non-selective muscarinic antagonist (M1, M2, M3); the slide names the drug and its use without its selectivity. On 10/5 he said benztropine is more selective for M1 in the brain than atropine, with fewer anti-DUMBBELSS effects elsewhere. Only the site of action (central nervous system) is keyed."},
{"id": "DL2-038", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "tropicamide", "tags": ["drug-list", "apply"], "source": "both", "fg": "classes", "stem": "Tropicamide dilates the pupil. Which mechanism explains this?", "options": [{"t": "It blocks M3, leaving the SNS unopposed", "correct": true, "why": "The parasympathetic system constricts the pupil through M3 (Gq → IP3, Ca++); blocking M3 leaves the sympathetic nervous system (SNS) unopposed → mydriasis."}, {"t": "It activates α1 receptors on the radial muscle", "correct": false, "why": "Activating α1 to cause mydriasis is phenylephrine."}, {"t": "It inhibits acetylcholinesterase in the eye", "correct": false, "why": "Inhibiting acetylcholinesterase in the eye (echothiophate) causes miosis."}, {"t": "It activates M3 receptors in the ciliary muscle", "correct": false, "why": "M3 activation constricts the pupil (miosis)."}], "teach": "The sympathetic nervous system (SNS) dilates the pupil and the parasympathetic nervous system (PNS) constricts it through M3 (Gq → PLC → IP3 and Ca++). Tropicamide blocks M3 in the eye, so the SNS is unopposed and the pupil dilates (mydriasis).", "quote": "Well, we know that the sympathetic cause pupil dilation. The parasympathetic cause pupil constriction. … So by blocking those M3s, I'm gonna get, instead of pupil constriction, I'm gonna get pupil dilation, also known as madriasis.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 26; transcript 10/5"},
{"id": "DL2-039", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "ipra-vs-tio", "tags": ["drug-list", "tell"], "source": "both", "fg": "classes", "stem": "Which statement correctly tells ipratropium and tiotropium apart?", "options": [{"t": "Ipratropium is short acting; tiotropium is long acting", "correct": true, "why": "Ipratropium is the short-acting muscarinic antagonist (SAMA, 3–4 times a day); tiotropium is a long-acting muscarinic antagonist (LAMA, once a day)."}, {"t": "Ipratropium is long acting; tiotropium is short acting", "correct": false, "why": "Reverses the two: ipratropium is the SAMA, tiotropium the LAMA."}, {"t": "Both are agonists at M3 in bronchial smooth muscle", "correct": false, "why": "Both are antagonists; M3 activation constricts the bronchi."}, {"t": "Both reach high levels in the blood after inhaling", "correct": false, "why": "Both were built for very low bioavailability, so they stay mainly in the lungs."}], "teach": "Both are inhaled muscarinic antagonists used in the lungs, where M3 (Gq → IP3, Ca++) constricts bronchial smooth muscle and only the parasympathetic system innervates. Ipratropium is a short-acting muscarinic antagonist (SAMA); tiotropium is a long-acting muscarinic antagonist (LAMA). Both have very low bioavailability and stay mainly in the airways.", "quote": "So we have, for example, ipratropium, that's the short acting called SAA, right? Or the teotropin-like drugs, which are called the lemmas.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 28; transcript 10/5", "note": "The slide gives ipratropium as M1, M2 and M3 and tiotropium as M1 and M3. On 10/5 he called both “less selective” and said either could affect M2 or M3 if it got into the circulation. The receptor profiles are therefore not keyed; short versus long acting is."},
{"id": "DL2-040", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "tiotropium-heart-rate", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Inhaled tiotropium is unlikely to change heart rate. Which of the following is the reason?", "options": [{"t": "It stays mainly in the lungs", "correct": true, "why": "Its structure gives very low bioavailability, so it stays in the airways and rarely reaches M2 in the heart."}, {"t": "It does not bind M2 receptors", "correct": false, "why": "Tiotropium is one of the less selective inhaled antagonists; it could affect M2 if it got into the circulation."}, {"t": "It is an agonist at M2 in the heart", "correct": false, "why": "Tiotropium is a muscarinic antagonist, not an agonist."}, {"t": "It activates β1 receptors in the heart", "correct": false, "why": "β1 is an adrenergic receptor; tiotropium is a muscarinic antagonist."}], "teach": "M2 receptors at the SA and AV node slow the heart, so blocking them would raise heart rate. Tiotropium and ipratropium are less selective inhaled muscarinic antagonists, but their chemical structure gives very low bioavailability, so they stay mainly in the lungs and seldom reach the heart.", "quote": "The ipratropium and the tiotropium are less selective, but what we have done for them is change their chemical structure so that they have very low bioavailability, so they stay primarily within the lungs. So even though they can affect the M2s or the M3s, it's very likely, unlikely because they don't get systemic.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3; PCOL-Cholinergic-26s.pdf slide 10, 28; transcript 10/5", "note": "The drug list says heart rate is not affected because tiotropium does not target M2, and the slide gives tiotropium as M1 and M3. On 10/5 he said tiotropium is less selective and could affect M2 if it went systemic, and that its low bioavailability keeps it in the lungs. Keyed to what he said."},
{"id": "DL2-041", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "aclidinium", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which statement about aclidinium and umeclidinium is CORRECT?", "options": [{"t": "They have high affinity for M3 and dissociate slowly", "correct": true, "why": "They bind M3 tightly (high affinity); binding is reversible, but dissociation is slow, so they are very long acting. Site of action: the lungs."}, {"t": "They are irreversible M3 antagonists", "correct": false, "why": "They are reversible, with slow dissociation."}, {"t": "They are muscarinic agonists for dry mouth", "correct": false, "why": "The muscarinic agonist used for dry mouth is pilocarpine."}, {"t": "They act on M3 in the bladder for overactive bladder", "correct": false, "why": "That is oxybutynin and the other overactive-bladder drugs."}], "teach": "Aclidinium and umeclidinium are inhaled muscarinic antagonists acting in the lungs. They bind M3 with high affinity and are more selective for M3 than ipratropium and tiotropium; the binding is reversible, but they dissociate slowly, so they are very long acting (long-acting muscarinic antagonists).", "quote": "And we have two drugs, the clinidiums in the bottom. Those are really long acting. … So they have a very high tight binding, so a very high affinity, and they're more selective to the M3s.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Cholinergic-26s.pdf slide 28; transcript 10/5"},
{"id": "DL2-042", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "soa-lungs", "tags": ["drug-list", "list"], "source": "both", "fg": "classes", "multi": true, "stem": "Which muscarinic antagonists have the lungs as their site of action? Select all that apply.", "options": [{"t": "Ipratropium", "correct": true, "why": "Inhaled; short-acting muscarinic antagonist."}, {"t": "Tiotropium", "correct": true, "why": "Inhaled; long-acting muscarinic antagonist."}, {"t": "Umeclidinium", "correct": true, "why": "Inhaled; high M3 affinity."}, {"t": "Oxybutynin", "correct": false, "why": "Site of action: M3 in the bladder."}, {"t": "Tropicamide", "correct": false, "why": "Site of action: the eye."}, {"t": "Benztropine", "correct": false, "why": "Site of action: the central nervous system."}], "teach": "The inhaled muscarinic antagonists (less systemic effect) are ipratropium, tiotropium, aclidinium and umeclidinium. In the lungs only the parasympathetic system innervates bronchial smooth muscle, where M3 causes bronchial constriction.", "quote": "So for example, if your patient has COPD and they use an inhaler, where do you want the drug to be at? In the lungs. … so that they have very low bioavailability, so they stay primarily within the lungs.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 3–4; PCOL-Cholinergic-26s.pdf slide 27–28; transcript 10/5"},
{"id": "DL2-043", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "moa-oab", "tags": ["drug-list"], "source": "both", "fg": "classes", "stem": "Which of the following describes the mechanism of action of oxybutynin?", "options": [{"t": "Muscarinic antagonist favoring M3", "correct": true, "why": "Oxybutynin and the other overactive-bladder drugs are non-selective, reversible muscarinic antagonists that are more selective toward bladder M3."}, {"t": "β3 agonist in bladder smooth muscle", "correct": false, "why": "That is mirabegron."}, {"t": "Non-selective muscarinic agonist", "correct": false, "why": "That is bethanechol, used for urinary retention."}, {"t": "α1 antagonist in the urethra", "correct": false, "why": "That is prazosin, terazosin, doxazosin and tamsulosin."}], "teach": "Oxybutynin, trospium and solifenacin are reversible muscarinic antagonists designed to be more selective toward the M3 receptors in the bladder. Blocking bladder M3 relaxes the bladder and decreases urgency, frequency and leakage in overactive bladder.", "quote": "So by giving this muscarinic antagonist and blocking the M3s in the bladder, we're gonna relax the bladder so you don't have that urgency of having to go potty all the time. … these drugs, they are designed, bless you, to be more selective to the M3s in the bladder", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Cholinergic-26s.pdf slide 29; transcript 10/5"},
{"id": "DL2-044", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "oab-cns", "tags": ["drug-list", "tell"], "source": "both", "fg": "classes", "stem": "Which statement about oxybutynin and solifenacin is CORRECT?", "options": [{"t": "Oxybutynin is more likely to cause sedation", "correct": true, "why": "Oxybutynin is less selective: it blocks M1 in the brain as well as M3, so it causes sedation; solifenacin is more selective for M3."}, {"t": "Solifenacin is more likely to cause sedation", "correct": false, "why": "Reversed: solifenacin is the more M3-selective drug, with fewer central effects."}, {"t": "Only oxybutynin can cause anti-DUMBBELSS", "correct": false, "why": "All of them can; a high enough dose of solifenacin gives all the anti-DUMBBELSS effects."}, {"t": "Both act mainly on M2 in the bladder", "correct": false, "why": "The bladder target is M3; M2 is the cardiac muscarinic receptor."}], "teach": "All overactive-bladder antagonists can cause anti-DUMBBELSS, especially dry mouth and constipation (M3). Central effects (drowsiness, dizziness, confusion) follow M1 block: oxybutynin (M1 and M3, the oldest and cheapest) most, and least the M3-selective solifenacin and trospium. At therapeutic doses the M3-selective drugs act more on the bladder and cause fewer anti-DUMBBELSS effects; at higher doses they cause them all.", "quote": "Now, oxybutynin over here, uh, when we look at their anti-muscarin effect, they are less selective. They can affect the M1s and they can affect the M3s. What effect they would have by affecting the M1s? What would be the site of action? The brain, right? So they'll cause sedation.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Cholinergic-26s.pdf slide 30; transcript 10/5", "note": "The drug list says solifenacin, darifenacin and trospium are “least likely to cause anti-DUMBBELSS”; the slide says all of them can cause anti-DUMBBELSS and places the three lowest for central effects. On 10/5 he said both: the M3-selective drugs cause fewer anti-DUMBBELSS effects at therapeutic doses, but “if I give enough of VESIcare, I’m gonna get all the anti-dumbbells”. He named oxybutynin, trospium and solifenacin as the three overactive-bladder drugs for the exam."},
{"id": "DL2-045", "lecture": "DL2", "prof": "Gottlieb", "tier": "new", "topic": "DL2", "sub": "chol", "skill": "drug", "concept": "adr-oab", "tags": ["drug-list", "list"], "source": "both", "fg": "classes", "multi": true, "stem": "Which adverse effects are shared by all the overactive-bladder muscarinic antagonists? Select all that apply.", "options": [{"t": "Xerostomia (dry mouth)", "correct": true, "why": "All muscarinic antagonists: M3 block on salivary glands."}, {"t": "Constipation", "correct": true, "why": "All muscarinic antagonists: M3 block in the gut."}, {"t": "Diarrhea", "correct": false, "why": "Diarrhea is a muscarinic agonist (DUMBBELSS) effect."}, {"t": "Miosis", "correct": false, "why": "Miosis is an agonist effect; antagonists dilate the pupil."}, {"t": "Bradycardia", "correct": false, "why": "Bradycardia is an agonist effect (M2); antagonists raise heart rate."}], "teach": "All overactive-bladder antagonists (oxybutynin, trospium, solifenacin and the others) have the potential to cause anti-DUMBBELSS; the more M3-selective ones need a higher dose to do so. The effects shared by all muscarinic antagonists through M3 are xerostomia (dry mouth) and constipation.", "quote": "If I give enough of VESIcare, I'm gonna get all the anti-dumbbells.", "cite": "Pharmacology_Exam_2_Drug_List.pdf page 4; PCOL-Cholinergic-26s.pdf slide 30; transcript 10/5"}
);
